fun reduce(state: UiState, intent: Intent): UiState = when (intent) {
    is Intent.Refresh -> {
        repository.refresh()
        state.copy(isLoading = true)
    }
    is Intent.Select -> state.copy(selectedId = intent.id)
}

private val intents = Channel<Intent>(Channel.UNLIMITED)

init {
    viewModelScope.launch {
        for (intent in intents) handle(intent)
    }
}
